INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'adaptation', 'n.', '/ˌædæpˈteɪʃn/', '适应;改编;改编本', 'Adaptation to a new culture takes time and patience.', '适应一种新文化需要时间和耐心。', 'Bridging Cultures', 1, 0, 'senior', 'wordlist', 'elective2', 'U2', 'adaptation to a new culture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'adapt', 'v.', '/əˈdæpt/', '适应;改编', 'At first, Xie Lei had to adapt to life in a different country.', '起初,谢蕾不得不适应在异国的生活。', 'Bridging Cultures', 2, 0, 'senior', 'wordlist', 'elective2', 'U2', 'adapt to life abroad', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'ambition', 'n.', '/æmˈbɪʃn/', '追求的目标;夙愿;抱负;野心', 'Her ambition is to set up a business in China after graduation.', '她的抱负是毕业后在中国创办一家企业。', 'Bridging Cultures', 3, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a great ambition', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'ambitious', 'adj.', '/æmˈbɪʃəs/', '有抱负的;有雄心的', 'An ambitious student is never afraid of a new challenge.', '一个有抱负的学生从不害怕新的挑战。', 'Bridging Cultures', 4, 0, 'senior', 'wordlist', 'elective2', 'U2', 'an ambitious student', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'applicant', 'n.', '/ˈæplɪkənt/', '申请人', 'Every applicant for the exchange programme must write a personal essay.', '每位交换项目的申请人都必须写一篇个人短文。', 'Bridging Cultures', 5, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a successful applicant', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'budget', 'n.', '/ˈbʌdʒɪt/', '预算', 'Students should think about their family''s budget before studying abroad.', '学生在出国留学前应考虑家庭的预算。', 'Bridging Cultures', 6, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a tight budget', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cite', 'v.', '/saɪt/', '引用;引述', 'Her tutor said she must acknowledge others if she cited their ideas.', '她的导师说,如果引用别人的观点,她必须注明出处。', 'Bridging Cultures', 7, 0, 'senior', 'wordlist', 'elective2', 'U2', 'cite their ideas', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'comfort', 'n./v.', '/ˈkʌmfət/', '安慰;舒适;安逸;抚慰', 'When she misses home, a second family gives her great comfort.', '想家时,第二个家庭给了她极大的安慰。', 'Bridging Cultures', 8, 0, 'senior', 'wordlist', 'elective2', 'U2', 'take comfort in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'competence', 'n.', '/ˈkɒmpɪtəns/', '能力;胜任;本领', 'Studying abroad helps you improve your general competence.', '出国留学有助于提高你的综合能力。', 'Bridging Cultures', 9, 0, 'senior', 'wordlist', 'elective2', 'U2', 'general competence', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'competent', 'adj.', '/ˈkɒmpɪtənt/', '有能力的;称职的', 'China needs young people who are highly competent with languages.', '中国需要语言能力很强的年轻人。', 'Bridging Cultures', 10, 0, 'senior', 'wordlist', 'elective2', 'U2', 'highly competent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'complex', 'adj.', '/ˈkɒmpleks/', '复杂的;难懂的', 'Living in a new culture can be more complex than students expect.', '生活在新文化中可能比学生预想的更复杂。', 'Bridging Cultures', 11, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a complex problem', '美音 /kəmˈpleks/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cooperate', 'v.', '/kəʊˈɒpəreɪt/', '合作;协作;配合', 'Cooperating with people from diverse backgrounds gives us new insight.', '与不同背景的人合作能给我们新的洞察。', 'Bridging Cultures', 12, 0, 'senior', 'wordlist', 'elective2', 'U2', 'cooperate with others', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'deny', 'v.', '/dɪˈnaɪ/', '否认;否定;拒绝(给予)', 'One cannot deny the fact that studying abroad has its difficulties.', '人们无法否认出国留学有其困难这一事实。', 'Bridging Cultures', 13, 0, 'senior', 'wordlist', 'elective2', 'U2', 'deny the fact', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'departure', 'n.', '/dɪˈpɑːtʃə(r)/', '离开;启程;出发', 'He will still remember his Chinese friends long after his departure.', '离开很久之后,他仍会记得他的中国朋友。', 'Bridging Cultures', 14, 0, 'senior', 'wordlist', 'elective2', 'U2', 'before his departure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'depress', 'v.', '/dɪˈpres/', '使沮丧;使忧愁', 'Failing to make friends abroad can depress many young students.', '在国外交不到朋友会让许多年轻学生感到沮丧。', 'Bridging Cultures', 15, 0, 'senior', 'wordlist', 'elective2', 'U2', 'depress someone', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'depressed', 'adj.', '/dɪˈprest/', '沮丧的;意志消沉的', 'Some students feel depressed when they first face culture shock.', '一些学生初次面对文化冲击时会感到沮丧。', 'Bridging Cultures', 16, 0, 'senior', 'wordlist', 'elective2', 'U2', 'feel depressed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'dramatic', 'adj.', '/drəˈmætɪk/', '巨大的;急剧的;戏剧性的', 'There has been a dramatic increase in the number of people studying abroad.', '出国留学的人数急剧增加。', 'Bridging Cultures', 17, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a dramatic increase', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'edition', 'n.', '/ɪˈdɪʃn/', '(报刊的)一份;(节目的)一期;版次', 'We will follow Xie Lei''s progress in later editions of the magazine.', '我们将在杂志的后续各期中关注谢蕾的进展。', 'Bridging Cultures', 18, 0, 'senior', 'wordlist', 'elective2', 'U2', 'in later editions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'engage', 'v.', '/ɪnˈɡeɪdʒ/', '参与;从事;吸引(注意力)', 'Engaging in British culture has helped her feel at home.', '融入英国文化让她感到自在。', 'Bridging Cultures', 19, 0, 'senior', 'wordlist', 'elective2', 'U2', 'engage in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'envoy', 'n.', '/ˈenvɔɪ/', '使者;使节;代表', 'Chinese students abroad can be seen as cultural envoys promoting friendship.', '海外的中国学生可被视为促进友谊的文化使者。', 'Bridging Cultures', 20, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a cultural envoy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'expectation', 'n.', '/ˌekspekˈteɪʃn/', '期望;预期;期待', 'The advisor talked about keeping reasonable expectations when studying abroad.', '顾问谈到了留学时要保持合理的期望。', 'Bridging Cultures', 21, 0, 'senior', 'wordlist', 'elective2', 'U2', 'reasonable expectations', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'expense', 'n.', '/ɪkˈspens/', '费用;花费;开销', 'Tuition fees and living expenses are much higher than at home.', '学费和生活费比在国内高得多。', 'Bridging Cultures', 22, 0, 'senior', 'wordlist', 'elective2', 'U2', 'living expenses', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'expose', 'v.', '/ɪkˈspəʊz/', '使接触;使体验;暴露', 'Studying abroad exposes students to a whole new way of thinking.', '出国留学使学生接触到一种全新的思维方式。', 'Bridging Cultures', 23, 0, 'senior', 'wordlist', 'elective2', 'U2', 'expose to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'exposure', 'n.', '/ɪkˈspəʊʒə(r)/', '接触;体验;暴露', 'Exposure to another culture can give students great insights into the world.', '接触另一种文化能给学生对世界的深刻见解。', 'Bridging Cultures', 24, 0, 'senior', 'wordlist', 'elective2', 'U2', 'exposure to another culture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'gain', 'v./n.', '/ɡeɪn/', '获得;赢得;好处', 'Studying abroad helps you gain a global perspective.', '出国留学有助于你获得全球视野。', 'Bridging Cultures', 25, 0, 'senior', 'wordlist', 'elective2', 'U2', 'gain a global perspective', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'grasp', 'v.', '/ɡrɑːsp/', '理解;领会;抓紧', 'It was difficult for her to grasp the Chinese tones at first.', '起初她很难掌握汉语的声调。', 'Bridging Cultures', 26, 0, 'senior', 'wordlist', 'elective2', 'U2', 'grasp the tones', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'homesickness', 'n.', '/ˈhəʊmsɪknəs/', '思乡;乡愁', 'Many exchange students suffer from homesickness in their first weeks.', '许多交换生在最初几周饱受思乡之苦。', 'Bridging Cultures', 27, 0, 'senior', 'wordlist', 'elective2', 'U2', 'suffer from homesickness', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'initiative', 'n.', '/ɪˈnɪʃətɪv/', '倡议;新方案', 'The Belt and Road Initiative has helped China connect with the world.', '“一带一路”倡议帮助中国与世界相连。', 'Bridging Cultures', 28, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the Belt and Road Initiative', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'insight', 'n.', '/ˈɪnsaɪt/', '洞察力;眼光;深刻见解', 'Cultural exchange gives us more insight into our own culture.', '文化交流让我们对自己的文化有更深的洞察。', 'Bridging Cultures', 29, 0, 'senior', 'wordlist', 'elective2', 'U2', 'gain insight into', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'involve', 'v.', '/ɪnˈvɒlv/', '使参与;包含;涉及', 'Getting involved in social activities is the best way to overcome culture shock.', '积极参与社交活动是克服文化冲击的最佳方式。', 'Bridging Cultures', 30, 0, 'senior', 'wordlist', 'elective2', 'U2', 'get involved in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'logical', 'adj.', '/ˈlɒdʒɪkl/', '合乎逻辑的;合情合理的', 'Good logical connectors help readers follow your reasoning.', '好的逻辑连接词能帮助读者跟上你的推理。', 'Bridging Cultures', 31, 0, 'senior', 'wordlist', 'elective2', 'U2', 'logical connectors', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'mature', 'adj.', '/məˈtʃʊə(r)/', '成熟的', 'Some students are not mature enough to handle the challenges alone.', '有些学生还不够成熟,无法独自应对挑战。', 'Bridging Cultures', 32, 0, 'senior', 'wordlist', 'elective2', 'U2', 'mature enough', '美音 /məˈtʊr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'messenger', 'n.', '/ˈmesɪndʒə(r)/', '送信人;信使', 'She is acting as a cultural messenger between China and the UK.', '她正充当中英之间的文化信使。', 'Bridging Cultures', 33, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a cultural messenger', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'motivate', 'v.', '/ˈməʊtɪveɪt/', '激发;激励', 'Living abroad can motivate students to work harder than ever.', '在国外生活能激励学生比以往更努力。', 'Bridging Cultures', 34, 0, 'senior', 'wordlist', 'elective2', 'U2', 'motivate students', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'motivated', 'adj.', '/ˈməʊtɪveɪtɪd/', '积极的;主动的;有干劲的', 'She became more motivated after she made new friends abroad.', '在国外结交新朋友后,她变得更有干劲了。', 'Bridging Cultures', 35, 0, 'senior', 'wordlist', 'elective2', 'U2', 'feel motivated', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'motivation', 'n.', '/ˌməʊtɪˈveɪʃn/', '动力;动机;积极性', 'The motivation for Xie Lei to study abroad was to learn about global business.', '谢蕾出国留学的动机是了解全球商业。', 'Bridging Cultures', 36, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the motivation to study abroad', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'optimistic', 'adj.', '/ˌɒptɪˈmɪstɪk/', '乐观的', 'There are no great difficulties for a person who is brave and optimistic.', '对于勇敢乐观的人来说,没有克服不了的困难。', 'Bridging Cultures', 37, 0, 'senior', 'wordlist', 'elective2', 'U2', 'stay optimistic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'outcome', 'n.', '/ˈaʊtkʌm/', '结果;效果', 'She decided to stay positive about the outcome of her studies.', '她决定对自己学业的结果保持乐观。', 'Bridging Cultures', 38, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a positive outcome', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'outlook', 'n.', '/ˈaʊtlʊk/', '前景;观点;视野', 'China''s global outlook has helped it make connections across the world.', '中国的全球视野帮助它与世界各地建立联系。', 'Bridging Cultures', 39, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a global outlook', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'overwhelming', 'adj.', '/ˌəʊvəˈwelmɪŋ/', '无法抗拒的;压倒性的;巨大的', 'The first few weeks abroad were absolutely overwhelming for her.', '在国外的最初几周对她来说是难以承受的。', 'Bridging Cultures', 40, 0, 'senior', 'wordlist', 'elective2', 'U2', 'absolutely overwhelming', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'participate', 'v.', '/pɑːˈtɪsɪpeɪt/', '参加;参与', 'She was always ready to participate in the activities her college offered.', '她总是乐于参加学院提供的各种活动。', 'Bridging Cultures', 41, 0, 'senior', 'wordlist', 'elective2', 'U2', 'participate in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'participation', 'n.', '/pɑːˌtɪsɪˈpeɪʃn/', '参加;参与', 'Many courses include students'' participation as part of the final result.', '许多课程把学生的课堂参与作为期末成绩的一部分。', 'Bridging Cultures', 42, 0, 'senior', 'wordlist', 'elective2', 'U2', 'class participation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'perspective', 'n.', '/pəˈspektɪv/', '(思考问题的)角度;观点', 'Studying abroad helps you gain a global perspective on the world.', '出国留学有助于你获得看待世界的全球视角。', 'Bridging Cultures', 43, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a global perspective', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'presentation', 'n.', '/ˌpreznˈteɪʃn/', '报告;陈述;演示', 'Her presentation on traditional Chinese art was a great success.', '她关于中国传统艺术的演讲非常成功。', 'Bridging Cultures', 44, 0, 'senior', 'wordlist', 'elective2', 'U2', 'give a presentation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'qualification', 'n.', '/ˌkwɒlɪfɪˈkeɪʃn/', '资格;学历;资历', 'Xie Lei is studying for a business qualification at a Chinese university.', '谢蕾正在一所中国大学攻读商科学历。', 'Bridging Cultures', 45, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a business qualification', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'reasonable', 'adj.', '/ˈriːznəbl/', '有道理的;合情理的;合理的', 'It is wise to keep reasonable expectations about life abroad.', '对国外生活保持合理的期望是明智的。', 'Bridging Cultures', 46, 0, 'senior', 'wordlist', 'elective2', 'U2', 'reasonable expectations', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'recall', 'v.', '/rɪˈkɔːl/', '记起;回想起', '"I was very excited but also quite nervous," Xie Lei recalled.', '“我很激动,但也相当紧张,”谢蕾回忆道。', 'Bridging Cultures', 47, 0, 'senior', 'wordlist', 'elective2', 'U2', 'recall the past', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'setting', 'n.', '/ˈsetɪŋ/', '环境;背景;情节背景', 'Understanding the setting helps you understand the conversation more clearly.', '理解情景有助于你更清楚地理解对话。', 'Bridging Cultures', 48, 0, 'senior', 'wordlist', 'elective2', 'U2', 'understand the setting', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'strengthen', 'v.', '/ˈstreŋθn/', '加强;增强;巩固', 'Talented young people will help further strengthen our country.', '有才华的年轻人将帮助进一步增强我们的国家。', 'Bridging Cultures', 49, 0, 'senior', 'wordlist', 'elective2', 'U2', 'strengthen our country', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'surroundings', 'n.', '/səˈraʊndɪŋz/', '环境;周围的事物', 'Some students suffer from culture shock in new surroundings.', '一些学生在新环境中会遭遇文化冲击。', 'Bridging Cultures', 50, 0, 'senior', 'wordlist', 'elective2', 'U2', 'new surroundings', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'tremendous', 'adj.', '/trəˈmendəs/', '巨大的;极大的', 'Studying abroad comes with tremendous pressure for many students.', '对许多学生来说,出国留学伴随着巨大的压力。', 'Bridging Cultures', 51, 0, 'senior', 'wordlist', 'elective2', 'U2', 'tremendous pressure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'tutor', 'n.', '/ˈtjuːtə(r)/', '导师;助教;家庭教师', 'Her tutor advised her to read a lot in order to form her own opinions.', '她的导师建议她广泛阅读以形成自己的观点。', 'Bridging Cultures', 52, 0, 'senior', 'wordlist', 'elective2', 'U2', 'her tutor', '美音 /ˈtuːtər/');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u2.01', '①宾语从句(that / whether / if / what 等)', 'A2', 11, '选择性必修二 U2 — 动词或介词后接宾语从句:陈述完整内容用 that;表''是否''用 whether/if(介词后只用 whether);从句缺成分(主/宾)用 what。', 1, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u2.02', '②主语从句 & 表语从句(What… / It… that… / The fact is that…)', 'A2', 11, '选择性必修二 U2 — 主语从句:从句缺成分用 What,完整内容用 that(或形式主语 It is… that…);表语从句:在 be 后用 that(完整)或 what(缺成分)。', 2, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u2.03', '③同位语从句(the fact/idea/news/question + that/whether…)', 'A2', 11, '选择性必修二 U2 — 抽象名词(fact/idea/news/question 等)后解释其内容用 that(不可省、不作成分);表''是否''用 whether;与定语从句区别:同位语 that 不作成分,定语从句 which/that 在从句中作主语或宾语。', 3, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Xie Lei said ____ she felt much more at home in the UK now.', 'that', 'what', 'which', 'whether', 'A', 'said 后接陈述内容、从句完整不缺成分 → that(只连接不充当成分)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'I don''t know ____ the exchange student will come to our class.', 'that', 'whether', 'what', 'which', 'B', '表''是否''、句意未定 → whether(that 表确定陈述,此处不合)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Please tell me ____ you need before you go abroad.', 'that', 'whether', 'what', 'if', 'C', 'tell me 后宾语从句缺 need 的宾语 → what(充当宾语;that 不作成分)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'At first she had no idea about ____ she should say in class.', 'that', 'which', 'if', 'what', 'D', '介词 about 后从句缺 say 的宾语 → what;介词后不用 that/if。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Her tutor explained ____ she must acknowledge other people''s ideas.', 'that', 'what', 'whether', 'how', 'A', 'explained 后陈述内容、从句完整 → that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'The advisor asked ____ the students had any worries about going abroad.', 'that', 'whether', 'what', 'which', 'B', 'asked 表''是否有''、未定 → whether(if 此处也行,但选项中只 whether 合且无 if)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Xie Lei was surprised at ____ the British people thought of Chinese culture.', 'that', 'if', 'what', 'whether', 'C', '介词 at 后从句缺 thought of 的宾语 → what;介词后不用 if/that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Leon couldn''t believe ____ many kinds of Chinese food there are.', 'that', 'which', 'whether', 'how', 'D', '感叹''有多么多''、修饰 many → how;此处非''是否''也非缺名词成分。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'The host family told Xie Lei ____ they were keen to learn about China.', 'that', 'what', 'if', 'which', 'A', 'told 后陈述内容、从句完整 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'She wondered ____ she should stick to her own way or follow the local way.', 'that', 'whether', 'what', 'how', 'B', 'wondered + 二选一''是否……还是'' → whether(常与 or 连用;that 不表选择)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Studying abroad changed ____ Xie Lei thought about the wider world.', 'that', 'if', 'how', 'whether', 'C', 'changed 后从句表''方式''、缺方式状语 → how(非''是否'',非缺名词成分)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'The interviewer asked the student ____ had impressed her most in China.', 'that', 'if', 'whether', 'what', 'D', '宾语从句缺主语 → what(充当主语;that 不作成分)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'I think ____ getting involved in activities is the best way to fit in.', 'that', 'what', 'whether', 'which', 'A', 'think 后陈述内容、从句完整 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Aisha was not sure ____ learning Chinese would help her future career.', 'that', 'whether', 'what', 'how', 'B', 'be not sure 表''是否''、未定 → whether。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Now she finally understood ____ her tutor had really wanted to say.', 'that', 'if', 'what', 'whether', 'C', 'understood 后从句缺 say 的宾语 → what。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'He often thinks about ____ his life would be like without his Chinese friends.', 'that', 'which', 'if', 'what', 'D', '介词 about 后从句缺 be like 的表语 → what;介词后不用 if/that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Wang Li believes ____ studying in China can help families save money.', 'that', 'what', 'whether', 'how', 'A', 'believes 后陈述内容、从句完整 → that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'The teacher asked us ____ we had ever suffered from culture shock.', 'that', 'whether', 'what', 'which', 'B', 'asked + ''是否曾经'' → whether(if 此处也可,但选项中只 whether 合且无 if)。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Cooperating with others taught her ____ a global mind really means.', 'that', 'if', 'what', 'how', 'C', 'taught her 后从句缺 means 的宾语 → what。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.01'), 'Listen carefully and decide ____ the conversation is probably happening.', 'that', 'which', 'whether', 'where', 'D', 'decide 后从句表''地点''、缺地点状语 → where(非陈述完整,故非 that)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ surprised Xie Lei was that she soon began speaking up in class.', 'What', 'That', 'Whether', 'Which', 'A', '主语从句缺 surprised 的主语 → What(充当主语;that 不作成分)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ Xie Lei keeps a balance between study and social life is important.', 'What', 'That', 'Whether', 'How', 'B', '主语从句内容完整、不缺成分 → That(只连接)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'It surprised everyone ____ she felt at home in the UK so quickly.', 'what', 'whether', 'that', 'which', 'C', '形式主语 It…，真主语从句完整 → that(It…that… 结构)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ impressed Leon first was the wonderful Chinese food.', 'That', 'Whether', 'How', 'What', 'D', '主语从句缺 impressed 的主语 → What。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ he should study abroad or stay in China is still undecided.', 'Whether', 'That', 'What', 'Which', 'A', '主语从句表''是否……还是''、句首 → Whether(句首不用 if)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'The truth is ____ getting involved in activities helps you overcome culture shock.', 'what', 'that', 'whether', 'how', 'B', '表语从句内容完整、不缺成分 → that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ Aisha said about Ms Hu''s family moved everyone in the room.', 'That', 'Whether', 'What', 'How', 'C', '主语从句缺 said 的宾语 → What。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'The fact is ____ tuition fees abroad are much higher than at home.', 'what', 'whether', 'which', 'that', 'D', '表语从句内容完整 → that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'It is clear ____ exposure to another culture broadens students'' minds.', 'that', 'what', 'whether', 'how', 'A', '形式主语 It is clear…，真主语从句完整 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ seemed strange to Xie Lei before now appears quite normal.', 'That', 'What', 'Whether', 'Which', 'B', '主语从句缺 seemed 的主语 → What。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'Her biggest worry was ____ she could make friends in a new country.', 'that', 'what', 'whether', 'which', 'C', '表语从句表''是否''、未定 → whether。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ the host family loved most was Xie Lei''s stir-fried tomatoes and eggs.', 'That', 'Whether', 'How', 'What', 'D', '主语从句缺 loved 的宾语 → What。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'It remains to be seen ____ her research paper will be well received.', 'whether', 'what', 'that', 'which', 'A', '形式主语 It…，真主语表''是否''、未定 → whether(不用 that/if)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'His ambition is ____ he will set up a successful business one day.', 'what', 'that', 'whether', 'how', 'B', '表语从句内容完整、不缺成分 → that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ made Aisha want to become a teacher was Ms Hu''s warm care.', 'That', 'Whether', 'What', 'Which', 'C', '主语从句缺 made 的主语 → What。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ studying abroad is worthwhile depends on each student''s situation.', 'That', 'What', 'How', 'Whether', 'D', '主语从句表''是否''、句首 → Whether(句首不用 if;非缺成分,故非 What)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'The good news is ____ her presentation on Chinese art was a great success.', 'that', 'what', 'whether', 'which', 'A', '表语从句内容完整 → that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ really motivated Leon was the kindness of the Chinese people.', 'That', 'What', 'Whether', 'How', 'B', '主语从句缺 motivated 的主语 → What。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), 'It is no surprise ____ many students suffer from homesickness at first.', 'what', 'whether', 'that', 'which', 'C', '形式主语 It is no surprise…，真主语完整 → that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.02'), '____ a student adapts to a new culture often decides how happy they feel.', 'That', 'Whether', 'What', 'How', 'D', '主语从句表''方式/程度''、缺方式状语 → How(非缺名词成分,故非 What)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The fact ____ studying abroad has disadvantages cannot be denied.', 'that', 'which', 'what', 'how', 'A', '同位语从句解释 fact 的内容、从句完整 → that(不可省、不作成分;which 须在从句作成分)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'She kept the idea ____ cultural exchange could build bridges between nations.', 'which', 'that', 'what', 'whether', 'B', '同位语从句解释 idea 的内容、从句完整 → that(which 不引导同位语从句)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'We received the news ____ Xie Lei''s exchange year had been a great success.', 'which', 'what', 'that', 'how', 'C', '同位语从句解释 news 的内容、从句完整 → that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The question ____ she should live with a host family troubled her for days.', 'that', 'which', 'what', 'whether', 'D', '同位语从句表''是否''解释 question → whether(question + whether;不用 if 引导同位语)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'He could not accept the fact ____ his classmates spoke so fast.', 'that', 'which', 'what', 'how', 'A', '同位语从句解释 fact、从句完整 → that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The belief ____ hard work brings success kept the students going.', 'which', 'that', 'what', 'whether', 'B', '同位语从句解释 belief、从句完整 → that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'I like the idea ____ China should tell its own stories to the world.', 'which', 'what', 'that', 'how', 'C', '同位语从句解释 idea、从句完整 → that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The question ____ to study abroad or not is one many families discuss.', 'that', 'which', 'what', 'whether', 'D', '同位语 + 不定式''是否……'' → whether(whether to do;不用 if to do)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'There is growing hope ____ more young people will become cultural envoys.', 'that', 'which', 'what', 'how', 'A', '同位语从句解释 hope、从句完整 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The advice ____ she should read widely helped her form her own opinions.', 'which', 'that', 'what', 'whether', 'B', '同位语从句解释 advice、从句完整 → that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The fact ____ she shared during the interview moved the whole audience.', 'what', 'whether', 'that', 'how', 'C', '此处从句缺 shared 的宾语 → 是定语从句,关系代词 that 在从句作宾语(对比同位语 that 不作成分)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'He raised the question ____ cashless payment had changed daily life in China.', 'that', 'which', 'what', 'whether', 'D', '同位语从句表''是否''解释 question → whether。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The idea ____ she first proposed was to start a Chinese culture club.', 'that', 'what', 'whether', 'how', 'A', '此处从句缺 proposed 的宾语 → 定语从句,that 在从句作宾语(非同位语,因从句缺成分)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'We must face the fact ____ adapting to a new culture is never easy.', 'which', 'that', 'what', 'how', 'B', '同位语从句解释 fact、从句完整 → that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The news ____ surprised the students was that the institute had grown so fast.', 'what', 'whether', 'that', 'how', 'C', '此处从句缺 surprised 的主语 → 定语从句,that 在从句作主语(对比同位语 that 不作成分)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'His doubt ____ he could pass the course slowly disappeared over time.', 'which', 'what', 'how', 'that', 'D', '同位语从句解释 doubt、从句完整 → that(doubt 在肯定语境后常用 that)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'There remains the question ____ studying abroad is worth such a high cost.', 'whether', 'that', 'which', 'what', 'A', '同位语从句表''是否''解释 question → whether。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The suggestion ____ students keep reasonable expectations is very helpful.', 'which', 'that', 'what', 'how', 'B', '同位语从句解释 suggestion、从句完整(虚拟 keep)→ that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'The discovery ____ she made about herself was that she could speak up.', 'what', 'whether', 'that', 'how', 'C', '此处从句缺 made 的宾语 → 定语从句,that 在从句作宾语(非同位语)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U2' AND code='e2u2.03'), 'We share the hope ____ the world can be brought closer together.', 'which', 'what', 'how', 'that', 'D', '同位语从句解释 hope、从句完整 → that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Xie Lei''s First Months Abroad', 'Six months ago, Xie Lei said goodbye to her family and boarded a plane for London. It was the first time she had left China, and she felt both excited and nervous. At first, she had to adapt to a whole new life. She learned how to use public transport and how to ask strangers for help when she got lost, even though people there spoke fast and used words she did not know. Instead of living in campus accommodation, she chose a host family, who comforted her whenever she missed home. Another challenge was the academic work. Her tutor wanted to know what she herself thought, not just what other people had said. This confused her at first, because she believed she knew less than others. Step by step, however, Xie Lei grew more confident and began to feel at home in a country that had once seemed so strange.', '记叙·留学生活的适应', 151, '[{"q":"How did Xie Lei feel as she left China for London?","answer":"A","options":["Both eager and worried.","Completely calm and bored.","Angry at her family.","Sure she would fail."],"explanation":"原文 ''felt both excited and nervous'' 的转述,非照抄。"},{"q":"Why did Xie Lei choose a host family instead of campus housing?","answer":"B","options":["Because it was cheaper than a dormitory.","Because they could comfort her when she missed home.","Because the school forced her to.","Because she wanted to live alone."],"explanation":"原文 ''a host family, who comforted her whenever she missed home'' 的转述。"},{"q":"What confused Xie Lei about her academic work at first?","answer":"A","options":["Her tutor valued her own thinking, not just others'' words.","Her tutor refused to help her at all.","She had no books to read.","She was not allowed to write essays."],"explanation":"原文 tutor ''wanted to know what she herself thought'' 的转述。"}]'::jsonb, '[{"word":"adapt","cn":"适应"},{"word":"accommodation","cn":"住宿"},{"word":"comfort","cn":"安慰"},{"word":"tutor","cn":"导师"}]'::jsonb, 2, 'elective2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'A Bridge Between Two Cultures', 'Now halfway through her exchange year, Xie Lei feels much more at home in Britain. What once seemed strange now appears quite normal to her. "Engaging in British culture has really helped," she says. As well as studying hard, she has taken part in many social activities. She has noticed that British people are fascinated by Chinese culture and eager to learn more about it, so she is keen to share her own traditions with them. Each evening she and her host family take turns to cook, and they especially love her stir-fried tomatoes and eggs. When Laura, the daughter of the family, said she always felt hungry at the smell of the dish, Xie Lei happily taught her how to make it too. In small moments like these, Xie Lei is doing more than studying business. She is acting as a cultural messenger, quietly building a bridge between China and the wider world.', '记叙·做文化使者', 154, '[{"q":"How does Xie Lei feel about Britain now, halfway through her year?","answer":"B","options":["Still completely lost.","Far more comfortable than before.","Eager to return home at once.","Bored with British life."],"explanation":"原文 ''feels much more at home'' 的转述。"},{"q":"Why is Xie Lei keen to share Chinese traditions?","answer":"C","options":["Because her tutor ordered her to.","Because she dislikes British food.","Because British people are curious about Chinese culture.","Because she wants to earn money."],"explanation":"原文 ''fascinated by Chinese culture and eager to learn more'' 的转述。"},{"q":"What does the writer mean by calling Xie Lei a ''cultural messenger''?","answer":"D","options":["She delivers letters between countries.","She teaches business at a university.","She works for a post office.","She helps connect China and the world through everyday exchange."],"explanation":"末段 ''building a bridge between China and the wider world'' 的转述。"}]'::jsonb, '[{"word":"engage","cn":"参与;融入"},{"word":"fascinated","cn":"着迷的"},{"word":"messenger","cn":"信使"},{"word":"bridge","cn":"桥梁"}]'::jsonb, 2, 'elective2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Why Studying Abroad Can Be Hard', 'In recent years there has been a dramatic increase in the number of young people studying abroad. Although it can bring great benefits, the difficulties should not be ignored. To begin with, many families face heavy economic pressure, because tuition fees and living expenses overseas are often far higher than at home. For some, the cost is simply too great. Besides money, there is the pressure of daily life. Students must learn to live in an unfamiliar place with limited language skills, and some suffer from culture shock when they try to behave correctly in new surroundings. Those who are not mature enough may struggle on their own and even become depressed. Different ways of teaching and learning can also come as a shock. None of this means that studying abroad is a bad choice. It simply means that students and their families should think carefully about these many factors before they make such an important decision.', '议论·留学的挑战', 157, '[{"q":"What has happened to the number of young people studying abroad?","answer":"A","options":["It has risen sharply.","It has stayed exactly the same.","It has dropped to almost zero.","It can no longer be counted."],"explanation":"原文 ''a dramatic increase in the number'' 的转述。"},{"q":"Why is money a problem for some families?","answer":"B","options":["Because foreign schools give no lessons.","Because fees and living costs abroad are often much higher.","Because students refuse to study.","Because banks are closed overseas."],"explanation":"原文 ''tuition fees and living expenses overseas are often far higher'' 的转述。"},{"q":"What is the writer''s overall attitude towards studying abroad?","answer":"C","options":["It is always a terrible mistake.","It should be banned completely.","Families should weigh the factors carefully before deciding.","Everyone must do it no matter what."],"explanation":"末段 ''think carefully about these many factors'' 的转述。"}]'::jsonb, '[{"word":"expense","cn":"费用"},{"word":"culture shock","cn":"文化冲击"},{"word":"mature","cn":"成熟的"},{"word":"depressed","cn":"沮丧的"}]'::jsonb, 2, 'elective2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Personal Growth Through Studying Abroad', 'Is studying abroad a good idea? There are certainly difficulties, but many parents believe the advantages are much greater. The first advantage is personal growth. Far from home, young people must deal with all kinds of problems by themselves, and so they quickly become more independent. They also gain a global perspective and improve their general competence. A second advantage is the chance for cultural exchange. Chinese students abroad can be seen as cultural envoys who promote friendship between nations, while international students bring their own colourful cultures to China. Cooperating with people from diverse backgrounds helps everyone view the world from different angles and gives deeper insight into their own culture. Finally, studying abroad offers a great chance to serve one''s country. With a global outlook and strong language skills, young people who study overseas can return with the abilities China needs, and these in turn will open up better career opportunities for them.', '议论·留学的益处', 155, '[{"q":"According to the writer, why does studying abroad lead to personal growth?","answer":"D","options":["Students never have to do anything alone.","Schools abroad have easier exams.","Parents do all the work for them.","Students must solve their own problems and become independent."],"explanation":"原文 ''deal with all kinds of problems by themselves… become more independent'' 的转述。"},{"q":"What does cooperating with people from diverse backgrounds do?","answer":"A","options":["It lets them look at the world from fresh viewpoints.","It makes students forget their own culture.","It only wastes their time.","It stops cultural exchange."],"explanation":"原文 ''view the world from different angles and gives deeper insight'' 的转述。"},{"q":"How can students who study abroad serve their country?","answer":"B","options":["By staying overseas forever.","By coming home with the global vision and abilities their country needs.","By avoiding all language learning.","By refusing any career."],"explanation":"末段 ''return with the abilities China needs'' 的转述。"}]'::jsonb, '[{"word":"perspective","cn":"视角"},{"word":"envoy","cn":"使者"},{"word":"cooperate","cn":"合作"},{"word":"insight","cn":"洞察"}]'::jsonb, 2, 'elective2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'A Teacher at the Confucius Institute', 'Aisha first met Chinese culture at a Confucius Institute in her own country. Her teacher, Ms Hu, often invited students to her home for festivals and home-cooked meals. The warm welcome made Aisha feel like part of the family, and that feeling stayed with her for years. She loved learning Chinese characters and the stories hidden inside them, and slowly she began to grasp the tones that had once seemed impossible. After graduation, Aisha decided to become a teacher herself, hoping to share the same warmth with new learners. Today she tells her students that knowing Chinese is good for their future, because more and more jobs need people who can connect China with the rest of the world. "Learning a language," she says, "is really learning a culture." For Aisha, the institute did far more than teach grammar. It opened a door to friendship and to a future she had never imagined.', '记叙·孔子学院与中文学习', 153, '[{"q":"What made Aisha feel like part of Ms Hu''s family?","answer":"C","options":["The high marks she received.","The free textbooks she got.","The warm invitations to festivals and home meals.","The size of the classroom."],"explanation":"原文 ''invited students to her home… made Aisha feel like part of the family'' 的转述。"},{"q":"Why did Aisha decide to become a teacher?","answer":"D","options":["To earn a large salary.","To leave her own country.","To stop learning Chinese.","To pass on that same kindness to those just starting Chinese."],"explanation":"原文 ''hoping to share the same warmth with new learners'' 的转述。"},{"q":"Why does Aisha think learning Chinese helps her students'' future?","answer":"A","options":["Because a growing number of careers value people who link China with other nations.","Because Chinese is easy to pronounce.","Because it requires no effort at all.","Because it replaces all other subjects."],"explanation":"原文 ''more and more jobs need people who can connect China with the rest of the world'' 的转述。"}]'::jsonb, '[{"word":"grasp","cn":"掌握"},{"word":"tone","cn":"声调"},{"word":"connect","cn":"连接"},{"word":"institute","cn":"学院"}]'::jsonb, 2, 'elective2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Telling China''s Story Well', 'When Leon, an exchange student from Germany, arrived in China, he expected to study hard but did not expect to fall in love with the country. What impressed him first was the food, and he could hardly believe how many kinds of Chinese dishes there are. He was also amazed that people could eat almost anything with chopsticks. Beyond food, he discovered China''s colourful culture, from calligraphy and music to ancient poems. He was surprised, too, by the convenience of cashless payment, going out each day with nothing but his phone. Yet the biggest reason he loves China is the people. He has made warm friends whom he will remember long after his departure. Stories like Leon''s show why telling China''s story well matters so much. When young people from other countries share what they have truly seen and felt, the world begins to understand China not through rumours, but through real and friendly human experience.', '议论·讲好中国故事', 156, '[{"q":"What impressed Leon first about China?","answer":"B","options":["The cold winter weather.","The many kinds of Chinese food.","The high price of phones.","The empty streets."],"explanation":"原文 ''What impressed him first was the food'' 的转述。"},{"q":"What does Leon say is the biggest reason he loves China?","answer":"C","options":["The cashless payment system.","The calligraphy classes.","The friendly people he has met.","The cheap transport."],"explanation":"原文 ''the biggest reason he loves China is the people'' 的转述。"},{"q":"Why does the writer think stories like Leon''s matter?","answer":"D","options":["They prove German food is the best.","They show that China should stay closed.","They encourage students to stop travelling.","They help the world understand China through real experience, not rumours."],"explanation":"末段 ''understand China not through rumours, but through real… experience'' 的转述。"}]'::jsonb, '[{"word":"calligraphy","cn":"书法"},{"word":"convenience","cn":"便利"},{"word":"departure","cn":"离开"},{"word":"rumour","cn":"谣言"}]'::jsonb, 2, 'elective2', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U2', 'My First Week Overseas', 'When I first arrived in a foreign country, everything felt (1)____ and a little frightening. I could not even read the signs at the airport, and I was afraid I would get (2)____ on my way to school. The first few weeks were truly (3)____, because the food, the streets and the language were all so different from home. I often (4)____ from homesickness and missed my mother''s cooking. My tutor told me not to worry and to give myself time to (5)____ to the new life. Little by little, I got (6)____ to the fast way people spoke, and I learned how to ask for (7)____ when I was unsure. I also chose to live with a (8)____ family, who welcomed me warmly and made me feel at (9)____. Looking back now, I am proud of how far a little daily (10)____ has taken me.', 146, 2, '[{"q":"1","answer":"A","options":["strange","boring","cheap","quiet"],"explanation":"everything felt strange 一切都很陌生。"},{"q":"2","answer":"B","options":["rich","lost","tall","famous"],"explanation":"get lost 迷路。"},{"q":"3","answer":"C","options":["funny","empty","overwhelming","useless"],"explanation":"truly overwhelming 令人难以承受。"},{"q":"4","answer":"D","options":["bought","sold","left","suffered"],"explanation":"suffer from homesickness 饱受思乡之苦。"},{"q":"5","answer":"A","options":["adapt","refuse","shout","sleep"],"explanation":"adapt to 适应。"},{"q":"6","answer":"B","options":["angry","used","afraid","tired"],"explanation":"get used to 习惯于。"},{"q":"7","answer":"C","options":["money","food","help","noise"],"explanation":"ask for help 求助。"},{"q":"8","answer":"D","options":["small","rich","busy","host"],"explanation":"a host family 寄宿家庭。"},{"q":"9","answer":"A","options":["home","school","war","risk"],"explanation":"feel at home 感到自在。"},{"q":"10","answer":"B","options":["error","effort","anger","silence"],"explanation":"daily effort 每天的努力。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U2', 'Beating Culture Shock', 'Many students feel (1)____ and lost during their first months in a new country. This feeling is often called culture (2)____. The good news is that there are simple ways to (3)____ it. The most useful advice is to get actively (4)____ in the activities around you, rather than staying alone in your room. Join a club, try the local food, and make (5)____ with classmates from different backgrounds. Every small step helps you feel more (6)____ and at ease. You should also keep (7)____ expectations, because no place is perfect and problems are normal. When you are not sure how to (8)____ in a new situation, simply watch what others do and ask politely. Remember the old saying: when in Rome, do as the (9)____ do. Step out of your comfort zone, and you will soon feel much more (10)____ in your new home.', 145, 2, '[{"q":"1","answer":"C","options":["proud","rich","confused","lazy"],"explanation":"feel confused 感到困惑。"},{"q":"2","answer":"D","options":["price","garden","machine","shock"],"explanation":"culture shock 文化冲击。"},{"q":"3","answer":"A","options":["overcome","sell","buy","forget"],"explanation":"overcome it 克服它。"},{"q":"4","answer":"B","options":["lost","involved","afraid","tired"],"explanation":"get involved in 参与。"},{"q":"5","answer":"C","options":["noises","prices","friends","mistakes"],"explanation":"make friends 交朋友。"},{"q":"6","answer":"D","options":["angry","bored","sorry","confident"],"explanation":"feel more confident 更自信。"},{"q":"7","answer":"A","options":["reasonable","empty","wrong","late"],"explanation":"reasonable expectations 合理的期望。"},{"q":"8","answer":"B","options":["sleep","behave","sell","lose"],"explanation":"how to behave 如何举止。"},{"q":"9","answer":"C","options":["teachers","sellers","Romans","drivers"],"explanation":"do as the Romans do 入乡随俗。"},{"q":"10","answer":"D","options":["afraid","alone","tired","at home"],"explanation":"feel at home 感到自在(此处取 at home)。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U2', 'Speaking Up in Class', 'In her first weeks abroad, Xie Lei found that many courses counted students'' (1)____ as part of the final grade. Teachers wanted everyone to generate ideas, offer (2)____, and raise questions, as well as give (3)____. At first Xie Lei had no idea what she should (4)____, and she stayed silent because she thought she knew (5)____ than the others. But something surprising (6)____ after just a few weeks: she found herself speaking up in class. Her (7)____ on traditional Chinese art was a great success, which boosted her (8)____ . She realised that the teachers were not looking for perfect answers, but for honest (9)____ . From then on, she was no longer afraid to share her own opinions, and she promised to use these new (10)____ when she returned home.', 132, 2, '[{"q":"1","answer":"A","options":["participation","weather","price","noise"],"explanation":"students'' participation 学生的参与。"},{"q":"2","answer":"B","options":["prices","examples","tickets","gardens"],"explanation":"offer examples 提供例子。"},{"q":"3","answer":"C","options":["machines","markets","presentations","errors"],"explanation":"give presentations 做演讲。"},{"q":"4","answer":"D","options":["sell","eat","buy","say"],"explanation":"what she should say 该说什么。"},{"q":"5","answer":"A","options":["less","more","older","taller"],"explanation":"knew less than others 懂得比别人少。"},{"q":"6","answer":"B","options":["stopped","happened","failed","disappeared"],"explanation":"something surprising happened 发生了一件令人惊讶的事。"},{"q":"7","answer":"C","options":["price","noise","presentation","garden"],"explanation":"her presentation 她的演讲。"},{"q":"8","answer":"D","options":["price","weather","noise","confidence"],"explanation":"boosted her confidence 增强了她的自信。"},{"q":"9","answer":"A","options":["thinking","selling","sleeping","shouting"],"explanation":"honest thinking 真实的思考。"},{"q":"10","answer":"B","options":["prices","skills","noises","machines"],"explanation":"these new skills 这些新技能。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U2', 'Sharing Chinese Culture', 'Living abroad gave me a wonderful chance to (1)____ my own culture with others. My foreign classmates were often (2)____ by Chinese traditions and eager to learn more. So I cooked a simple dish of tomatoes and eggs, and everyone (3)____ it at once. I also taught a friend how to write her name in Chinese (4)____ , and she was amazed by the beauty of each stroke. Through these small (5)____ , I was doing more than studying. I felt like a cultural (6)____ , building a (7)____ between my country and theirs. People in other countries are truly (8)____ about China, and they often know it only through rumours. When we (9)____ what we have really seen and felt, the world begins to understand China through real (10)____ instead of guesses.', 133, 2, '[{"q":"1","answer":"C","options":["hide","sell","share","lose"],"explanation":"share my culture 分享我的文化。"},{"q":"2","answer":"D","options":["bored","angry","tired","fascinated"],"explanation":"be fascinated by 被……迷住。"},{"q":"3","answer":"A","options":["loved","dropped","broke","lost"],"explanation":"everyone loved it 大家都喜欢。"},{"q":"4","answer":"B","options":["food","characters","money","noise"],"explanation":"Chinese characters 汉字。"},{"q":"5","answer":"C","options":["prices","machines","moments","errors"],"explanation":"small moments 小小的时刻。"},{"q":"6","answer":"D","options":["price","garden","market","messenger"],"explanation":"a cultural messenger 文化信使。"},{"q":"7","answer":"A","options":["bridge","noise","price","garden"],"explanation":"build a bridge 搭建桥梁。"},{"q":"8","answer":"B","options":["afraid","curious","sorry","tired"],"explanation":"curious about China 对中国好奇。"},{"q":"9","answer":"C","options":["hide","sell","share","drop"],"explanation":"when we share 当我们分享时。"},{"q":"10","answer":"D","options":["price","noise","machine","experience"],"explanation":"real experience 真实的体验。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U2', 'A Hard Choice for the Family', 'Whether to study abroad or stay at home is a (1)____ that many Chinese families discuss for a long time. On one hand, studying overseas is often very (2)____ , and the high tuition fees and living costs can put great (3)____ on parents. Some young people are not (4)____ enough to handle the challenges alone and may become (5)____ when they feel lonely. On the other hand, studying abroad can help a student (6)____ a global perspective and become more (7)____ . It also offers a chance for cultural (8)____ between nations. In the end, there is no single right answer. Each family must (9)____ all these factors carefully before they make such an important (10)____ . What matters most is that the choice fits the student''s own situation and dreams.', 132, 2, '[{"q":"1","answer":"A","options":["question","garden","price","machine"],"explanation":"a question 一个问题。"},{"q":"2","answer":"B","options":["cheap","expensive","quiet","empty"],"explanation":"very expensive 很昂贵。"},{"q":"3","answer":"C","options":["noise","music","pressure","weather"],"explanation":"put great pressure on 给……很大压力。"},{"q":"4","answer":"D","options":["rich","tall","loud","mature"],"explanation":"mature enough 足够成熟。"},{"q":"5","answer":"A","options":["depressed","proud","rich","famous"],"explanation":"become depressed 变得沮丧。"},{"q":"6","answer":"B","options":["lose","gain","sell","drop"],"explanation":"gain a global perspective 获得全球视野。"},{"q":"7","answer":"C","options":["lazy","afraid","independent","bored"],"explanation":"more independent 更独立。"},{"q":"8","answer":"D","options":["price","noise","garden","exchange"],"explanation":"cultural exchange 文化交流。"},{"q":"9","answer":"A","options":["weigh","sell","drop","hide"],"explanation":"weigh all these factors 权衡所有这些因素。"},{"q":"10","answer":"B","options":["noise","decision","price","machine"],"explanation":"an important decision 重要的决定。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U2', 'Building Bridges Between Nations', 'Young people who study abroad can do much more than earn a (1)____ . They can act as cultural envoys who (2)____ friendship between nations. International students who come to China bring their own (3)____ cultures, while Chinese students overseas share the stories of their homeland. When people from different backgrounds (4)____ together, they begin to view the world from new (5)____ . With projects such as the Belt and Road (6)____ , China has made more and more (7)____ across the world. This means the country now needs talented young people who are highly (8)____ with languages and have a strong global (9)____ . By learning from one another and respecting their differences, these young bridge-builders help to (10)____ a shared future for everyone.', 125, 2, '[{"q":"1","answer":"C","options":["noise","garden","degree","machine"],"explanation":"earn a degree 取得学位。"},{"q":"2","answer":"D","options":["break","sell","lose","promote"],"explanation":"promote friendship 促进友谊。"},{"q":"3","answer":"A","options":["colourful","empty","quiet","boring"],"explanation":"colourful cultures 多彩的文化。"},{"q":"4","answer":"B","options":["sleep","cooperate","sell","hide"],"explanation":"cooperate together 一同合作。"},{"q":"5","answer":"C","options":["prices","noises","angles","machines"],"explanation":"from new angles 从新的角度。"},{"q":"6","answer":"D","options":["noise","garden","price","Initiative"],"explanation":"the Belt and Road Initiative “一带一路”倡议。"},{"q":"7","answer":"A","options":["connections","prices","noises","errors"],"explanation":"make connections 建立联系。"},{"q":"8","answer":"B","options":["lazy","competent","afraid","tired"],"explanation":"highly competent 能力很强。"},{"q":"9","answer":"C","options":["price","noise","outlook","garden"],"explanation":"a global outlook 全球视野。"},{"q":"10","answer":"D","options":["break","sell","drop","build"],"explanation":"build a shared future 建设共同的未来。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·对话 Signing Up for the Exchange', '选择性必修二 U2 · dialogue', 3, 'Tom: Hi, Mei. I heard you signed up for the exchange programme to the UK.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·短文 Studying Abroad Today', '选择性必修二 U2 · passage', 2, 'In recent years, more and more young people choose to study abroad.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·对话 Interview at the Confucius Institute', '选择性必修二 U2 · dialogue', 3, 'Host: Welcome, Aisha. Thanks for joining us today.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·短文 A Tip on Weak Forms', '选择性必修二 U2 · passage', 2, 'Here is a useful tip for learners who find fast English hard to follow.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·对话 Advice on Fitting In', '选择性必修二 U2 · dialogue', 3, 'Liu: I''ve been here a month, but I still feel like an outsider. Any advice?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U2 听力·短文 Becoming a Cultural Envoy', '选择性必修二 U2 · passage', 2, 'When you study in another country, you do more than attend classes.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'Introduce Your School and Culture to Visiting Students(向来访学生介绍你的学校与文化)', 'Welcome to Our School', '假设你叫李华,一批来自澳大利亚的交换生即将到你校学习一年。请用英语写一篇约100词的欢迎短文,内容包括:① 热情欢迎并简单介绍你的学校(校训/社团/特色活动任选);② 分享一两个本地或中国文化的亮点(如书法、美食、节日);③ 表示愿意帮助他们适应、做他们的朋友。注意:用上名词性从句、连接词,行文连贯。', 'Suppose you are Li Hua. A group of exchange students from Australia will come to study at your school for a year. Write a welcome message (about 100 words) including: 1) a warm welcome and a brief introduction to your school (motto, clubs or special events); 2) one or two highlights of local or Chinese culture you would like to share (e.g. calligraphy, food, festivals); 3) your wish to help them adapt and be their friend.', '["热情欢迎并介绍学校(校训/社团/特色活动)","分享一两个中国/本地文化亮点(书法/美食/节日)","表示愿意帮助他们适应、做朋友","用上名词性从句与连接词,句句围绕中心、连贯"]'::jsonb, 70, 100, 'Dear friends, on behalf of our school, I am happy that you have chosen to study with us for a year. Welcome! Our school motto is "The best preparation for tomorrow is doing your best today." We have many clubs and exciting events, such as our Sports Meet and Art Festival, so I am sure you will soon feel at home. What I would love to share most is our culture. You can try writing your name in Chinese calligraphy and tasting dishes like tomatoes and eggs. If you ever feel lost or homesick, please tell me. I will gladly help you adapt and be your friend.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["On behalf of our school, I am happy that you have chosen to study with us for a year.","What I would love to share most is our culture.","I am sure you will soon feel at home.","If you ever feel lost or homesick, please tell me."]'::jsonb, '[{"wrong":"Welcome to our school study.","correct":"Welcome to study at our school.","note":"welcome to do sth 用动词原形,不用名词堆叠。"},{"wrong":"What I want to share is about our culture.","correct":"What I want to share is our culture.","note":"主语从句 What… 已含成分,表语后不再加 about。"},{"wrong":"I will help you to adapt the new life.","correct":"I will help you adapt to the new life.","note":"adapt 后接 to;help sb do 用原形。"}]'::jsonb, '【欢迎介绍信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective2', 'U2', '{"title":"名词性从句·连接词选择速查(宾语 / 主语 / 表语 / 同位语从句)","intro":"名词性从句把一个句子当作名词来用(作宾语、主语、表语或同位语)。判断连接词只看两点:① 从句缺不缺成分;② 内容是陈述、是''是否''、还是带疑问意义。口诀:缺成分用 what/who/which;不缺只连接用 that;表''是否''用 whether(/if)。","table":{"headers":["连接词","用法 / 例句"],"rows":[["that","只连接、不作成分、内容完整:I know that he is here. / the fact that…"],["whether / if","表''是否'':I wonder whether he will come.(介词后/句首/同位语/+or not/+to do 只用 whether)"],["what","充当主/宾/表语:What he said is true. / I don''t know what you need."],["who / which / how / where / when","带疑问意义、在从句中作相应成分或状语:who came / how it works"]]},"specialRules":[{"rule":"宾语从句:陈述完整用 that(口语可省);表''是否''用 whether/if","mark":"I think (that) he is right. / I don''t know whether/if he is right."},{"rule":"主语从句:缺成分用 What;完整用 That;常用形式主语 It is… that…","mark":"What he said is true. / That he came surprised us. / It is clear that…"},{"rule":"表语从句:在 be 后,完整用 that,缺成分用 what","mark":"The truth is that we are late. / The problem is what we should do."},{"rule":"同位语从句:解释 fact/idea/news/question 等抽象名词,that 不可省、不作成分","mark":"the news that he won(对比定语从句 the news that surprised us:that 作主语)"}],"why":["that 本身没有意义、不充当成分,只起''连接''作用,所以从句必须内容完整;一旦从句缺了主语、宾语或表语,就得换成能''充当成分''的 what/who/which 等。判断同位语从句还是定语从句,也只看从句缺不缺成分:缺成分=定语从句(which/that 作成分),不缺=同位语从句(that 只连接)。"],"gaokaoPoints":["that 与 what 的辨析(看从句是否缺成分)是语法填空与单选高频点。","介词后、句首、+or not、+ to do 只用 whether,不用 if;同位语从句也只用 whether 不用 if。","同位语从句 vs 定语从句的判断(that 是否在从句中作主语/宾语)。"],"examVsReal":[{"exam":"I don''t know whether he will come.（考试/书面）","real":"I don''t know if he''ll come.","note":"动词后宾语从句中 if=whether,口语更常用 if;但介词后/句首/同位语仍须 whether。"},{"exam":"I think that he is honest.（考试可写 that）","real":"I think he''s honest.","note":"口语里宾语从句的 that 几乎总被省略,书面正式场合保留更稳妥。"}]}'::jsonb);
